  if (canSwitch) {
    aggro.lastTargetSwitchTurn = turn;
    aggro.threatLockUntilTurn = turn + 1;
    setAggroTarget(world, owner, aggro, top.sourceId, String(opts.reason || "threat"));
    return top.sourceId;
  }
  return current;
}

